void unregister_ppp_channel(struct ppp_channel *chan) {
    if (!chan)
        return;

    /* Set PPP pointer to NULL */
    chan->ppp = NULL;

    /* Acquire write lock to ensure ongoing operations are completed */
    write_lock(&chan->lock);

    /* Disconnect the channel */
    ppp_channel_down(chan);

    /* Remove from the list of all channels */
    list_del(&chan->list);

    /* Decrement reference count of the channel's file structure */
    if (chan->file) {
        struct file *file = chan->file;
        if (file->f_count > 0)
            file->f_count--;

        /* Destroy the channel if reference count is zero */
        if (file->f_count == 0) {
            ppp_destroy_channel(chan);
        }

        /* Wake up processes waiting on the channel's file */
        wake_up_interruptible(&file->wait);
    }

    write_unlock(&chan->lock);
}

